#include <stdio.h>

int main() {
    int numbers[] = {1, 2, 3, 4, 5, 6, 7, 8};
    int total = sizeof(numbers) / sizeof(numbers[0]);
    int evens = 0;
    for (int i = 0; i < total; i++) {
        if (numbers[i] % 2 == 0) {
            evens++;
        }
    }
    printf("%d %d\n", evens, total - evens);
    return 0;
}
